import{_ as o,o as t,c as a,a2 as s}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"RFC 0084 — UI-driven backup & restore","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign/blob/main/docs/rfcs/0084-ui-driven-backup-restore.md"},"headers":[],"relativePath":"rfcs/0084-ui-driven-backup-restore.md","filePath":"rfcs/0084-ui-driven-backup-restore.md"}'),n={name:"rfcs/0084-ui-driven-backup-restore.md"};function i(r,e,d,c,l,p){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="rfc-0084-—-ui-driven-backup-restore" tabindex="-1">RFC 0084 — UI-driven backup &amp; restore <a class="header-anchor" href="#rfc-0084-—-ui-driven-backup-restore" aria-label="Permalink to &quot;RFC 0084 — UI-driven backup &amp; restore&quot;">​</a></h1><p><strong>Status:</strong> Partially implemented (epic tasks 8.16 and 8.18 shipped; epic task 8.17&#39;s backup half shipped at v0.128.0 — the guarded restore flow, maintenance-mode gate, and typed confirmation remain pending)<br><strong>Date:</strong> August 2026<br><strong>Author:</strong> kasunben<br><strong>Scope:</strong> new <code>backup_jobs</code> table (<code>packages/db</code>), new <code>runtime/src/backup-worker.ts</code>, new <code>runtime/app/api/backup-jobs/**</code>, new <code>plugins/console/app/backups/**</code>, extends <code>plugins/account/app/data/page.tsx</code> / <code>PortabilityPanel.tsx</code>, extends <code>runtime/src/portability/assemble.ts</code>, a new <code>sv backup --exclude-plugin</code> flag on <code>bin/sv.ts</code> (spawned as a subprocess, otherwise unchanged), <code>.env.example</code>. Amends RFC 0007 (resolves Open Questions #2 and #7) and layers on top of RFC 0068. Relates to, but does not depend on, RFC 0064.<br><strong>Incorporated into plan:</strong> Yes — epic tasks 8.16, 8.17, 8.18.</p><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Add a UI-driven, asynchronous backup and restore feature. Owners and admins get a Console page to back up and restore the whole instance; every other user gets an Account page to back up their own data (restore reuses the existing import flow). Both backup flows are asynchronous: triggering a backup creates a tracked job, the archive is generated in the background, encrypted with a passphrase the requester supplies, and delivered via a time-bounded signed download link once ready — the requester can leave and come back later. Console&#39;s flow additionally supports pushing the encrypted archive to a configured Git remote, and its restore flow is a guarded, in-app live restore with a maintenance-mode gate and an automatic pre-restore safety snapshot.</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>Sovereign has two backup-adjacent systems today and neither is reachable from a browser. Operators have <code>sv backup</code>/<code>sv restore</code> (RFC 0006) — a real, working, full-instance mechanism, but CLI-only, synchronous, and with no UI anywhere in Console. Regular users have per-user data export/import (RFC 0007, RFC 0033, RFC 0052, RFC 0068) via Account&#39;s <code>PortabilityPanel.tsx</code> — but it is fully synchronous with a hard-coded ceiling (<code>MAX_EXPORT_BYTES</code>, 50 MB), and RFC 0007 has carried two open questions since it shipped: whether export should ever be asynchronous with a signed link (&quot;Sync vs async export&quot;), and whether a user should be able to choose which plugins/categories to include (&quot;Selective export&quot;). RFC 0068 explicitly chose the synchronous-with-ceiling design over a background job for its own scope — this RFC revisits that choice because the underlying requirement has changed: both audiences now need a feature that survives being larger or slower than one HTTP request, and comes with a real place to click a button and get it.</p><p>This also matters for Sovereign&#39;s positioning: self-hosted, privacy-first instances are exactly the ones without a managed backup service behind them — the operator (and, for their own data, every user) is the backup story. A CLI-only mechanism is a real gap for the non-technical owner/admin persona this platform targets alongside developers.</p><h2 id="current-state-what-this-builds-on" tabindex="-1">Current state (what this builds on) <a class="header-anchor" href="#current-state-what-this-builds-on" aria-label="Permalink to &quot;Current state (what this builds on)&quot;">​</a></h2><ul><li><strong><code>sv backup</code>/<code>sv restore</code></strong> (<code>bin/sv.ts:508-751</code>, RFC 0006, implemented): full-instance, dialect-detected (SQLite: whole <code>data/</code> dir tarred, including isolated plugin DBs and WAL/SHM sidecars; Postgres: <code>pg_dump --format=custom</code> per platform/auth DB), local <code>.tar.gz</code> archive under <code>./backups</code>, CLI-only, no selective/per-plugin scope, plaintext by default (encryption is inherited only when the source SQLite files are already SQLCipher-encrypted per RFC 0071). <code>sv restore</code> extracts in place; SQLite restore has marker-reconciliation logic (<code>bin/sv.ts:696-746</code>) to avoid RFC 0071&#39;s &quot;key wrong&quot; failure mode when restoring a pre-encryption backup onto an encrypted instance — this logic is load-bearing and was exercised for real in the 2026-07-24 incident (<code>docs/incidents/2026-07-24-rfc-0071-encryption-rollout.md</code>).</li><li><strong><code>sv db encrypt</code>/<code>decrypt</code></strong> (<code>bin/sv.ts:~815-1045</code>) auto-run a full backup as a safety net before converting files unless <code>--skip-backup</code> is passed (<code>bin/sv.ts:886-891,1009-1014</code>) — the precedent this RFC&#39;s automatic pre-restore safety snapshot mirrors.</li><li><strong>RFC 0064</strong> (<code>docs/rfcs/0064-git-backed-operator-backups.md</code>, Status: Draft, unbuilt, epic tasks 8.10-8.12 pending) designs an encrypted <code>backup-manifest.json</code>, a Git-remote push/pull backend, retention/deletion, and scoped plugin restore — all still CLI-only by its own scope statement (&quot;No public SDK or UI package semver impact is expected&quot;). Its own Open Question #3 asks whether Console should ever expose backup/retention status — this RFC is that answer, arrived at independently rather than by waiting for 8.10-8.12.</li><li><strong>User data portability</strong> (RFC 0007 implemented; <code>runtime/src/portability/</code>): <code>assembleExport()</code> (<code>runtime/src/portability/assemble.ts</code>) builds a versioned ZIP in-memory by calling each eligible, opted-in plugin&#39;s registered <code>sdk.portability.provideExport</code> resolver (<code>packages/sdk/src/portability.ts</code>); <code>applyImport()</code> (<code>runtime/src/portability/restore.ts</code>) does the additive-merge reverse. <code>GET /api/account/export</code> / <code>POST /api/account/import</code> (<code>runtime/app/api/account/{export,import}/route.ts</code>) are both synchronous, session-gated to the requester&#39;s own <code>userId</code>, capped at <code>MAX_EXPORT_BYTES</code>/ <code>MAX_IMPORT_BYTES</code> (50 MB). <code>ExportContext</code> already carries an <code>options: ExportOptions</code> bag with an <code>includeFiles</code> toggle — the extension point for per-plugin selection this RFC adds to. <code>PortabilityPanel.tsx</code> (Account → Data tab) does a plain <code>fetch</code> → <code>res.blob()</code> → synthetic <code>&lt;a download&gt;</code> click; no polling, no job concept.</li><li><strong>RFC 0068</strong> (implemented) added <code>installedPlugins</code>/<code>notExported</code> to <code>BundleManifest</code> and explicitly decided the sync-vs-async question as &quot;a documented, enforced ceiling... rather than a background job&quot; for its own scope — this RFC adds the async path alongside that decision, not reversing it; the existing synchronous endpoint keeps working for small quick exports.</li><li><strong>No async job infrastructure exists.</strong> <code>sdk.jobs</code> (RFC 0046) is unbuilt — its own status header says &quot;Partially implemented (Phase 1 subset)... No queue, persistence, retries, cron, or <code>sdk.jobs</code> API yet.&quot; The only thing that runs code outside a request today is <code>runtime/src/scheduler.ts</code>, a fixed-interval 60-second-tick sweep for manifest-declared recurring schedules, whose own doc comment states it is &quot;deliberately NOT a job queue.&quot;</li><li><strong><code>sdk.storage</code></strong> (RFC 0044, implemented, <code>runtime/src/storage.ts</code>) is real but unsuitable for this feature as-is: local-filesystem-only, default caps of 25 MiB/object and 500 MiB/plugin-total (<code>storage.ts:13-14</code>, both env-overridable), signed URLs hard-capped at 1 hour (<code>MAX_SIGNED_URL_TTL_SECONDS</code>, <code>storage.ts:9-10</code>), and the download route (<code>runtime/app/api/storage/[token]/route.ts</code>) buffers the whole object in memory rather than streaming — none of this fits a multi-plugin or whole-instance archive that might be hundreds of megabytes and needs a &quot;come back tomorrow&quot; download window.</li><li><strong>Console conventions</strong>: Server Actions returning a shared <code>ActionResult</code> union for <code>useActionState</code> (e.g. <code>plugins/console/app/settings/actions.ts:11</code>), <code>sdk.auth.hasCapability(session, &#39;&lt;capability&gt;&#39;)</code> checks in both actions and pages, <code>adminOnly</code> route-prefix gating in runtime middleware (<code>docs/architecture-rules.md:157-159</code>) for <code>platform:admin</code>/<code>platform:owner</code>, <code>ConfirmDialog</code> (<code>@sovereignfs/ui</code>) as the sanctioned destructive-action pattern with async <code>onConfirm</code> support. The existing &quot;admin-managed external provider config&quot; encrypted-secret pattern (<code>plugins/console/app/settings/SmtpSettingsForm.tsx</code>) is the precedent this RFC reuses for storing a Git remote token, rather than inventing a new secret-storage mechanism.</li></ul><h2 id="proposed-design" tabindex="-1">Proposed design <a class="header-anchor" href="#proposed-design" aria-label="Permalink to &quot;Proposed design&quot;">​</a></h2><h3 id="shared-primitive-backup-jobs" tabindex="-1">Shared primitive: <code>backup_jobs</code> <a class="header-anchor" href="#shared-primitive-backup-jobs" aria-label="Permalink to &quot;Shared primitive: `backup_jobs`&quot;">​</a></h3><p>A new Drizzle table in <code>packages/db</code> (platform DB, both dialects):</p><ul><li><code>id</code>, <code>scope</code> (<code>&#39;instance&#39; | &#39;user&#39;</code>), <code>requestedByUserId</code>, <code>tenantId</code>, <code>status</code> (<code>&#39;queued&#39; | &#39;running&#39; | &#39;complete&#39; | &#39;failed&#39;</code>), <code>optionsJson</code> (selected/excluded plugin ids, git-push flag), <code>archivePath</code> (absolute path on local disk — deliberately outside <code>sdk.storage</code>&#39;s object model, for the size/streaming/TTL reasons above), <code>sizeBytes</code>, <code>errorMessage</code>, <code>createdAt</code>, <code>startedAt</code>, <code>completedAt</code>, <code>expiresAt</code>.</li></ul><h3 id="worker-runtime-src-backup-worker-ts" tabindex="-1">Worker: <code>runtime/src/backup-worker.ts</code> <a class="header-anchor" href="#worker-runtime-src-backup-worker-ts" aria-label="Permalink to &quot;Worker: `runtime/src/backup-worker.ts`&quot;">​</a></h3><p>A new sibling module to <code>scheduler.ts</code>, not a repurposing of it — mirrors its interval-tick + conditional-<code>UPDATE</code>-claim idempotency pattern (safe under multiple workers/restarts) rather than reusing its recurring-schedule-only code path, since <code>scheduler.ts</code>&#39;s own doc comment states it is deliberately not a job queue. Each tick: claim one queued <code>backup_jobs</code> row (<code>UPDATE ... WHERE status = &#39;queued&#39; ... LIMIT 1</code> equivalent), mark it <code>running</code>, do the work below, mark <code>complete</code>/<code>failed</code>, and separately sweep archive files past their <code>expiresAt</code> for cleanup. The runtime is a persistent Node process (PM2/Docker, not serverless — <code>docs/self-hosting.md</code>), so this in-process worker is a legitimate, simple design; it does not need to survive a process restart mid-job (a <code>running</code> job orphaned by a restart is swept back to <code>failed</code> on next boot).</p><ul><li><strong>Instance-scope job:</strong> spawns <code>pnpm sv backup</code> (existing CLI, unchanged archive logic) as a child process, passing the job&#39;s options via a new <code>--exclude-plugin &lt;id&gt;</code> flag (repeatable) — the one actual CLI change this RFC needs. Captures stdout/stderr and enforces a hard timeout so a hung subprocess cannot leave a job stuck <code>running</code> forever. Captures the resulting archive path.</li><li><strong>User-scope job:</strong> calls the existing <code>assembleExport()</code> directly (in-process, no subprocess needed) with <code>ExportOptions</code> extended to carry a per-plugin inclusion list (resolves RFC 0007 Open Question #7 — &quot;Selective export&quot;). The async path has no <code>MAX_EXPORT_BYTES</code> ceiling; the existing synchronous <code>GET /api/account/export</code> endpoint is untouched and keeps its ceiling for quick small exports.</li><li><strong>Encryption (both scopes, always applied — no opt-out):</strong> AES-256-GCM via Node&#39;s built-in <code>crypto</code>, key derived from the requester-supplied passphrase via <code>scrypt</code>. This resolves RFC 0007 Open Question #4 (&quot;Bundle encryption&quot;) and is this RFC&#39;s answer to RFC 0064&#39;s still-open Question #1 (&quot;age recipients, passphrase AES-GCM, or both&quot;) for its own narrower scope: passphrase-based AES-GCM, zero new dependencies. Recipient-based (age) encryption is left as a future enhancement, not needed for a single requester downloading their own backup. The passphrase is never persisted — it must be supplied again at download time (see below), not embedded in the signed URL, so a leaked link alone cannot decrypt the archive.</li><li><strong>Optional Git push (instance-scope only):</strong> if Git-remote credentials are configured (<code>SV_BACKUP_GIT_REPOSITORY</code>/<code>SV_BACKUP_GIT_TOKEN</code> — reusing RFC 0064&#39;s env var names for forward compatibility even though this RFC does not depend on RFC 0064 landing), the worker pushes the encrypted archive as an orphan commit tagged <code>sv-backup/&lt;timestamp&gt;/v&lt;platform&gt;</code>, the same shape RFC 0064 proposes. <strong>No retention, listing, or pruning of remote backups in v1</strong> — that stays epic task 8.12&#39;s scope, deferred. When 8.10-8.12 eventually land, this RFC&#39;s local manifest and Git-push code should be reconciled into RFC 0064&#39;s format rather than left as a permanent second format; this is a named follow-up, not a blocker for either RFC.</li></ul><h3 id="signed-download-delivery" tabindex="-1">Signed download delivery <a class="header-anchor" href="#signed-download-delivery" aria-label="Permalink to &quot;Signed download delivery&quot;">​</a></h3><p>A new route, <code>runtime/app/api/backup-jobs/[jobId]/download/[token]/route.ts</code>, HMAC-signed opaque token construction in the same style as <code>runtime/app/api/storage/[token]/route.ts</code>, but: a configurable TTL (default 48 hours, not the storage route&#39;s 1-hour ceiling), and streaming from disk via <code>createReadStream</code> rather than buffering the whole archive in memory. The passphrase used to encrypt must be re-entered at download time to decrypt client-side or server-side before the browser receives bytes (implementation detail for the leg that builds this — either is acceptable as long as the passphrase never rides in the URL/token itself).</p><h3 id="notification-on-completion" tabindex="-1">Notification on completion <a class="header-anchor" href="#notification-on-completion" aria-label="Permalink to &quot;Notification on completion&quot;">​</a></h3><p>Reuse the existing notification broker that already reaches <code>NotificationBell</code>/ <code>sdk.notifications</code> today to tell the requester &quot;your backup is ready&quot; with a link to the job/download page. The exact platform-level (non-plugin) integration point is confirmed during implementation (Leg 1 detail in the companion workstream), since today&#39;s <code>sdk.notifications.send</code> is a plugin-scoped SDK call keyed by <code>pluginId</code>, and this needs to fire from platform-owned code, not a plugin.</p><h3 id="console-ui-—-instance-backup-restore-owner-admin" tabindex="-1">Console UI — instance backup &amp; restore (owner/admin) <a class="header-anchor" href="#console-ui-—-instance-backup-restore-owner-admin" aria-label="Permalink to &quot;Console UI — instance backup &amp; restore (owner/admin)&quot;">​</a></h3><p>New <code>plugins/console/app/backups/page.tsx</code>, gated the same way every other admin-only Console page is (<code>adminOnly</code> route prefix + <code>hasCapability</code> checks in its Server Actions).</p><ul><li><strong>Backup:</strong> a trigger form (checkboxes to exclude specific installed plugins, a required passphrase field, an optional &quot;also push to a Git remote&quot; checkbox shown only when credentials are configured — stored via the same encrypted-secret pattern <code>SmtpSettingsForm.tsx</code> already establishes for admin-managed external provider config, not a new mechanism), a job list showing queued/running/complete/failed status with download links, and git-push status when applicable.</li><li><strong>Restore:</strong> pick a previous instance backup or upload an archive, then a guarded flow: (1) a validation/compatibility preview — platform version, DB dialect, plugin manifest compatibility, pulling forward the same checks RFC 0064&#39;s &quot;Restore guards&quot; section already specifies, implemented here directly rather than waiting on that RFC; (2) a maintenance-mode toggle the admin must explicitly enable; (3) an automatic pre-restore safety snapshot, mirroring <code>sv db encrypt</code>&#39;s existing auto-backup-before-convert precedent; (4) a typed confirmation (the admin types the instance name, the same friction level <code>ConfirmDialog</code>&#39;s async-<code>onConfirm</code> pattern supports); (5) execution, in-process, using the same restore logic <code>sv restore</code> already uses.</li></ul><h3 id="account-ui-—-async-user-data-backup-every-user" tabindex="-1">Account UI — async user data backup (every user) <a class="header-anchor" href="#account-ui-—-async-user-data-backup-every-user" aria-label="Permalink to &quot;Account UI — async user data backup (every user)&quot;">​</a></h3><p>Extends <code>plugins/account/app/data/page.tsx</code> / <code>PortabilityPanel.tsx</code> with a new &quot;Full backup&quot; action alongside (not replacing) the existing synchronous quick export button: per-plugin inclusion checkboxes, a required passphrase field, job status, and a signed download link once ready. <strong>Restore stays the existing import flow</strong> (<code>POST /api/account/import</code>, additive-merge) — importing an already-downloaded file the user has locally is fast and bounded, so it does not need the job/async treatment the way <em>generating</em> an export does; only backup gets the new async path.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><ol><li><strong>Wait for RFC 0064 (8.10-8.12) to land first, and build this RFC&#39;s UI directly on its manifest/encryption format.</strong> Would avoid a second local manifest format existing even temporarily. Rejected per explicit product decision: RFC 0064 is Draft with no scheduled timeline, and the UI gap is independently valuable now; the reconciliation cost of merging two formats later is accepted as a known, named follow-up rather than a blocker.</li><li><strong>CLI-only restore; Console only stages/validates and tells the admin to run <code>sv restore</code> themselves.</strong> Materially safer (no web request can trigger a live destructive restore), but does not satisfy &quot;restore via UI,&quot; which was explicit in the product ask. Rejected in favor of an in-app live restore with maintenance-mode gating, an automatic safety snapshot, and typed confirmation as the mitigations.</li><li><strong>Two-step gated restore</strong> (admin must separately enter maintenance mode as its own action before an in-app restore control unlocks at all). More friction, marginally safer than a single combined flow. Rejected in favor of folding the maintenance-mode toggle into the guided restore flow itself — the guardrails (compatibility preview, safety snapshot, typed confirmation) are judged sufficient without a separate prerequisite step.</li><li><strong>Block this feature on RFC 0046&#39;s <code>sdk.jobs</code> maturing first</strong>, and build backup on top of the general-purpose plugin job system once it exists. Rejected: <code>sdk.jobs</code> is barely started (Phase 1 subset, no queue/retries/ persistence yet) and is a plugin-facing SDK surface with its own separate design pressures; blocking a concrete, scoped feature on an unrelated, unscheduled SDK effort is worse than building a small, purpose-built job table now. If Leg 1&#39;s scope grows past &quot;minimal,&quot; that is this workstream&#39;s own kill-criteria signal to switch tracks, not a reason to wait up front.</li><li><strong>No archive encryption in v1</strong>, matching <code>sv backup</code>&#39;s current plaintext-by-default posture. Rejected: <code>docs/security.md</code> already states plainly that raw backups expose data if leaked, and that posture is far more consequential once a backup is reachable via a web-downloadable signed URL instead of a local CLI-only file. Encryption is mandatory, not optional, in this design.</li><li><strong>Reuse <code>sdk.storage</code> for archive delivery</strong> instead of a dedicated route. Rejected on concrete limits: 25 MiB/object and 500 MiB/plugin-total default caps, a 1-hour hard ceiling on signed URLs, and a download route that buffers the whole object in memory — none of which fit a potentially large, &quot;come back later&quot; archive.</li></ol><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ol><li>Exact platform-level (non-plugin) notification integration point — resolve during Leg 1 of the companion workstream, not blocking the RFC itself.</li><li>Whether <code>sv backup --exclude-plugin</code> should also gain an <code>--include-plugin</code> allowlist form, or whether exclude-only is sufficient for v1.</li><li>Whether the Git remote token should be entered once per instance (global, Settings-style) or could ever be scoped per-backup — proposed default is global/instance-wide, matching how <code>SmtpSettingsForm.tsx</code>&#39;s external provider config already works.</li><li>Whether a failed job should auto-retry once, or always require the requester to re-trigger manually — proposed default is manual re-trigger for v1 simplicity.</li></ol><h2 id="adoption-path" tabindex="-1">Adoption path <a class="header-anchor" href="#adoption-path" aria-label="Permalink to &quot;Adoption path&quot;">​</a></h2><p>Maps 1:1 to three epic tasks (<code>docs/epics/data-sovereignty.md</code>):</p><ol><li><strong>Epic task 8.16</strong> — <code>backup_jobs</code> table, <code>backup-worker.ts</code>, the passphrase-AES-GCM encryption helper, and the signed-download route. Pure platform primitive, nothing user-facing yet.</li><li><strong>Epic task 8.17</strong> — Console instance backup &amp; restore UI, the <code>--exclude-plugin</code> CLI flag, optional Git push, and the guarded restore flow. Depends on 8.16 and 8.1.</li><li><strong>Epic task 8.18</strong> — Account async selective backup UI. Depends on 8.16, 8.2, 8.8, 8.13.</li></ol><p>No public SDK or UI package (<code>@sovereignfs/sdk</code>, <code>@sovereignfs/ui</code>) semver impact is expected — this is runtime/Console/Account application code, not a plugin-facing contract change. <code>docs/self-hosting.md</code> and <code>.env.example</code> need updates for the new Git-push env vars once Leg 2 (epic task 8.17) implements them.</p><h2 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Date</th><th>Change</th></tr></thead><tbody><tr><td>0.1</td><td>August 2026</td><td>Initial draft</td></tr></tbody></table>',36)])])}const g=o(n,[["render",i]]);export{h as __pageData,g as default};
